DEFAULT_SALES_RATE_KEY = "default_sales_rate"

class Order:

    def __init__(self):
        self._menu = []
        # menu = [{"dish": dish name, "price": price, "count": count}, ...]
        self._selected_dishes = []
        # selected_dish = {"dish": dish name, "count": count, price: price}
        self._sales = {}

    @property
    def menu(self):
        return list(self._menu)

    @menu.setter
    def menu(self, menu):
        self._menu = list(menu)

    @property
    def selected_dishes(self):
        return list(self._selected_dishes)

    @selected_dishes.setter
    def selected_dishes(self, selected_dishes):
        self._selected_dishes = list(selected_dishes)

    @property
    def sales(self):
        return dict(self._sales)

    @sales.setter
    def sales(self, sales):
        self._sales = dict(sales)

    def _can_add_dish(self, dish):
        for menu_dish in self._menu:
            if dish["dish"] == menu_dish["dish"]:
                if menu_dish["count"] < dish["count"]:
                    return False
                return True
        return True

    def _sufficient_stock(self, dish):
        for menu_dish in self._menu:
            if dish["dish"] == menu_dish["dish"]:
                return menu_dish["count"] >= dish["count"]
        return True

    def _reduce_stock(self, dish):
        for menu_dish in self._menu:
            if dish["dish"] == menu_dish["dish"]:
                menu_dish["count"] -= dish["count"]
                break

    def _calculate_dish_total(self, dish):
        sales_rate = self._sales.get(dish["dish"], self._sales.get(DEFAULT_SALES_RATE_KEY, 1.0))
        return dish["price"] * dish["count"] * sales_rate

    def _has_selected_dishes(self):
        return len(self._selected_dishes) > 0

    def _clear_selected_dishes(self):
        self._selected_dishes = []

    def add_dish(self, dish):
        if not self._sufficient_stock(dish):
            return False
        self._reduce_stock(dish)
        self._selected_dishes.append(dish)
        return True

    def calculate_total(self):
        return sum(self._calculate_dish_total(dish) for dish in self._selected_dishes)

    def checkout(self):
        if not self._has_selected_dishes():
            return False
        total = self.calculate_total()
        self._clear_selected_dishes()
        return total
